prompt --application/shared_components/plugins/template_component/amc_next_compare
begin
wwv_flow_imp_shared.create_plugin(
 p_id=>wwv_flow_imp.id(970810790386401038)
,p_plugin_type=>'TEMPLATE COMPONENT'
,p_name=>'AMC_NEXT_COMPARE'
,p_display_name=>'Next Compare'
,p_supported_component_types=>'REPORT'
,p_partial_template=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<span class="amc-NCompare-srcOption" data-f="option">#OPTION#</span>{if ?OPTION_DETAIL/} <span class="amc-NCompare-srcDetail" data-f="optionDetail">#OPTION_DETAIL#</span>{endif/}',
'<span class="amc-NCompare-srcCrit">{if ?CRITERION_GROUP/}<span data-f="group">#CRITERION_GROUP#</span>: {endif/}<span data-f="criterion">#CRITERION#</span></span>',
'<span class="amc-NCompare-srcValue" data-f="value">#VALUE#</span>{if ?SCORE/} <span class="amc-NCompare-srcScore">Score <span data-f="score">#SCORE#</span></span>{endif/}{if ?WEIGHT/} <span class="amc-NCompare-srcWeight">Weight <span data-f="weight">#WEIGHT#</span></span>{endif/}',
'{if ?NOTE/}<span class="amc-NCompare-srcNote" data-f="note">#NOTE#</span>{endif/}'))
,p_default_escape_mode=>'HTML'
,p_translate_this_template=>true
,p_api_version=>1
,p_report_body_template=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<div class="amc-NCompare amc-NCompare--#STYLE#" data-variant="#STYLE#" data-score-max="#SCORE_MAX#" data-hide-identical="#HIDE_IDENTICAL#" data-pinned="#PINNED_OPTION#" data-totals="#SHOW_TOTALS#">',
'  <span class="amc-NCompare-i18n" hidden data-criterion="Criterion" data-weight="Weight" data-total="Weighted total" data-rank="Rank" data-best="Best in this row" data-leader="Leading" data-tied="Tied" data-pin="Pin %0" data-unpin="Unpin %0" data-pinned="%0 pinned as the first column" data-unpinned="Pin removed" data-hide="Hide identical rows" data-hidden="%0 identical rows hidden" data-none-identical="No identical rows" data-shown="Identical rows shown" data-prev="Previous option" data-next="Next option" data-position="%0 of %1" data-baseline="Baseline" data-same="Same as baseline" data-better="Better than baseline" data-worse="Worse than baseline" data-changed="Differs from baseline" data-yes="Included" data-no="Not included" data-standings="Weighted total out of 100" data-points="points" data-calculated="Scored from value" data-missing="No value" data-success="Strong point" data-warning="Needs attention" data-danger="Does not comply" data-info="Note" data-caption="Comparison of %0 options by %1 criteria"></span>',
'  <ul class="amc-NCompare-source">#APEX$ROWS#</ul>',
'</div>'))
,p_report_row_template=>'<li class="amc-NCompare-row" data-better="#BETTER#" data-highlight="#HIGHLIGHT#">#APEX$PARTIAL#</li>'
,p_css_file_urls=>'#PLUGIN_FILES#amc-next-compare.css'
,p_javascript_file_urls=>'#PLUGIN_FILES#amc-next-compare.js'
,p_substitute_attributes=>true
,p_subscribe_plugin_settings=>true
,p_help_text=>'One query row per option and criterion. Map Option, Criterion and Value. Score (0 to Score Maximum) and Weight turn on weighted totals and ranks; Better = lower or higher lets numeric values such as price or lead time be scored and compared without a Score. Criterion Group adds group bands such as Technical and Financial. Highlight flags a single cell. Without JavaScript the rows render as a readable list grouped by option.'
,p_version_identifier=>'1.0.0'
,p_files_version=>1
);
wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(498614047566174026)
,p_plugin_id=>wwv_flow_imp.id(970810790386401038)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>1
,p_display_sequence=>10
,p_static_id=>'STYLE'
,p_prompt=>'Style'
,p_attribute_type=>'SELECT LIST'
,p_is_required=>true
,p_default_value=>'tenderTable'
,p_escape_mode=>'ATTR'
,p_is_translatable=>false
,p_lov_type=>'STATIC'
,p_help_text=>'Comparison design; the direction is given after the name. tenderTable - smart: procurement evaluation sheet with criterion groups, a weight column, a standings strip that shows the gap between bidders, weighted total and rank rows and the leading column marked. specSheet - bold: datasheet with heavy rules, large option names, inverted group bands and yes / no values shown as marks with text. scorecard - motion: every cell carries a score bar; bars grow as they scroll into view and columns glide to their new place when an option is pinned. sideCards - depth: each option is a stack of quotation pages with aligned rows, the leader lifted forward. diffView - smart: every option compared with a baseline (the pinned option, or the first one) with signed differences marked better or worse; identical rows start hidden. Every style switches to one option at a time with swipe when the region is narrower than about 640 px. Under reduced motion nothing moves.'
);
wwv_flow_imp_shared.create_plugin_attr_value(
 p_id=>wwv_flow_imp.id(436286475880496542)
,p_plugin_attribute_id=>wwv_flow_imp.id(498614047566174026)
,p_display_sequence=>10
,p_display_value=>'Tender Table - smart'
,p_return_value=>'tenderTable'
);
wwv_flow_imp_shared.create_plugin_attr_value(
 p_id=>wwv_flow_imp.id(587289582014881730)
,p_plugin_attribute_id=>wwv_flow_imp.id(498614047566174026)
,p_display_sequence=>20
,p_display_value=>'Spec Sheet - bold'
,p_return_value=>'specSheet'
);
wwv_flow_imp_shared.create_plugin_attr_value(
 p_id=>wwv_flow_imp.id(380282002939705971)
,p_plugin_attribute_id=>wwv_flow_imp.id(498614047566174026)
,p_display_sequence=>30
,p_display_value=>'Scorecard - motion'
,p_return_value=>'scorecard'
);
wwv_flow_imp_shared.create_plugin_attr_value(
 p_id=>wwv_flow_imp.id(219972052117803373)
,p_plugin_attribute_id=>wwv_flow_imp.id(498614047566174026)
,p_display_sequence=>40
,p_display_value=>'Side Cards - depth'
,p_return_value=>'sideCards'
);
wwv_flow_imp_shared.create_plugin_attr_value(
 p_id=>wwv_flow_imp.id(988753075984152010)
,p_plugin_attribute_id=>wwv_flow_imp.id(498614047566174026)
,p_display_sequence=>50
,p_display_value=>'Diff View - smart'
,p_return_value=>'diffView'
);
wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(689724696999661338)
,p_plugin_id=>wwv_flow_imp.id(970810790386401038)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>2
,p_display_sequence=>20
,p_static_id=>'OPTION'
,p_prompt=>'Option'
,p_attribute_type=>'SESSION STATE VALUE'
,p_is_required=>true
,p_escape_mode=>'HTML'
,p_is_translatable=>false
,p_help_text=>'The thing being compared, for example a vendor, plan or candidate name such as Najd Industrial Supply. Options appear in the order of their first row; order the query by option display order, then criterion order.'
);
wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(543438015879534486)
,p_plugin_id=>wwv_flow_imp.id(970810790386401038)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>3
,p_display_sequence=>30
,p_static_id=>'CRITERION'
,p_prompt=>'Criterion'
,p_attribute_type=>'SESSION STATE VALUE'
,p_is_required=>true
,p_escape_mode=>'HTML'
,p_is_translatable=>false
,p_help_text=>'What is compared, for example Total price incl. VAT, Delivery lead time or Warranty. Criteria appear in the order of their first row.'
);
wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(490159410383097772)
,p_plugin_id=>wwv_flow_imp.id(970810790386401038)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>4
,p_display_sequence=>40
,p_static_id=>'VALUE'
,p_prompt=>'Value'
,p_attribute_type=>'SESSION STATE VALUE'
,p_is_required=>false
,p_escape_mode=>'HTML'
,p_is_translatable=>false
,p_help_text=>'The value as users should read it, for example SAR 412,500, 45 days, Yes or 24 months. When Better is set, the first number in the text is used for comparing, so keep one number per value.'
);
wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(543362477724574668)
,p_plugin_id=>wwv_flow_imp.id(970810790386401038)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>5
,p_display_sequence=>50
,p_static_id=>'SCORE'
,p_prompt=>'Score'
,p_attribute_type=>'SESSION STATE VALUE'
,p_is_required=>false
,p_escape_mode=>'HTML'
,p_is_translatable=>false
,p_help_text=>'Optional evaluation score from 0 to Score Maximum as a plain number, for example 8.5. The highest score in a criterion is marked best. Criteria without scores but with Better set are scored automatically: lowest value / value x maximum for lower, value / highest value x maximum for higher.'
);
wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(845827653719351112)
,p_plugin_id=>wwv_flow_imp.id(970810790386401038)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>6
,p_display_sequence=>60
,p_static_id=>'WEIGHT'
,p_prompt=>'Weight'
,p_attribute_type=>'SESSION STATE VALUE'
,p_is_required=>false
,p_escape_mode=>'HTML'
,p_is_translatable=>false
,p_help_text=>'Optional weight of the criterion, for example 30 for 30%. The first non-empty value per criterion is used, so it may be repeated on every row. Weights do not need to add up to 100; totals are normalised to a 0 to 100 scale. When no criterion has a weight, scored criteria count equally.'
);
wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(329063080510881950)
,p_plugin_id=>wwv_flow_imp.id(970810790386401038)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>7
,p_display_sequence=>70
,p_static_id=>'NOTE'
,p_prompt=>'Note'
,p_attribute_type=>'SESSION STATE VALUE'
,p_is_required=>false
,p_escape_mode=>'HTML'
,p_is_translatable=>false
,p_help_text=>'Optional short remark shown under the value, for example Excludes installation or Confirmed by site visit.'
);
wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(186295233247259301)
,p_plugin_id=>wwv_flow_imp.id(970810790386401038)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>8
,p_display_sequence=>80
,p_static_id=>'HIGHLIGHT'
,p_prompt=>'Highlight'
,p_attribute_type=>'SESSION STATE VALUE'
,p_is_required=>false
,p_escape_mode=>'ATTR'
,p_is_translatable=>false
,p_help_text=>'Optional flag for one cell: success, warning, danger or Y (information). For example danger for a bid that fails a mandatory requirement. It is shown with a mark and screen-reader text, never by color alone.'
);
wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(270174516497938682)
,p_plugin_id=>wwv_flow_imp.id(970810790386401038)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>9
,p_display_sequence=>90
,p_static_id=>'CRITERION_GROUP'
,p_prompt=>'Criterion Group'
,p_attribute_type=>'SESSION STATE VALUE'
,p_is_required=>false
,p_escape_mode=>'HTML'
,p_is_translatable=>false
,p_help_text=>'Optional group of the criterion, for example Technical or Financial. Groups appear as bands in the order of their first row, with the sum of their weights.'
);
wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(981621646092366010)
,p_plugin_id=>wwv_flow_imp.id(970810790386401038)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>10
,p_display_sequence=>100
,p_static_id=>'BETTER'
,p_prompt=>'Better'
,p_attribute_type=>'SESSION STATE VALUE'
,p_is_required=>false
,p_escape_mode=>'ATTR'
,p_is_translatable=>false
,p_help_text=>'Optional direction per criterion: lower (price, lead time, deductible) or higher (capacity, warranty, area). It marks the best value, sets better / worse in Diff View and scores unscored criteria. The first non-empty value per criterion is used.'
);
wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(579818827696173743)
,p_plugin_id=>wwv_flow_imp.id(970810790386401038)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>11
,p_display_sequence=>110
,p_static_id=>'OPTION_DETAIL'
,p_prompt=>'Option Detail'
,p_attribute_type=>'SESSION STATE VALUE'
,p_is_required=>false
,p_escape_mode=>'HTML'
,p_is_translatable=>false
,p_help_text=>'Optional second line under the option name, for example the city, a quotation reference such as Q-7781 or a plan price. The first non-empty value per option is used.'
);
wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(762531377054187519)
,p_plugin_id=>wwv_flow_imp.id(970810790386401038)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>12
,p_display_sequence=>120
,p_static_id=>'SCORE_MAX'
,p_prompt=>'Score Maximum'
,p_attribute_type=>'NUMBER'
,p_is_required=>false
,p_default_value=>'10'
,p_escape_mode=>'ATTR'
,p_is_translatable=>false
,p_help_text=>'The top of the Score scale, for example 10, 5 or 100. Bars and automatic scores use it.'
);
wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(865836012207461470)
,p_plugin_id=>wwv_flow_imp.id(970810790386401038)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>13
,p_display_sequence=>130
,p_static_id=>'HIDE_IDENTICAL'
,p_prompt=>'Hide Identical Rows'
,p_attribute_type=>'CHECKBOX'
,p_is_required=>false
,p_default_value=>'N'
,p_escape_mode=>'ATTR'
,p_is_translatable=>false
,p_help_text=>'Y starts with rows hidden where every option has the same value. Users can switch it with the Hide identical rows button. Diff View always starts with them hidden.'
);
wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(705640577165786314)
,p_plugin_id=>wwv_flow_imp.id(970810790386401038)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>14
,p_display_sequence=>140
,p_static_id=>'PINNED_OPTION'
,p_prompt=>'Pinned Option'
,p_attribute_type=>'TEXT'
,p_is_required=>false
,p_escape_mode=>'ATTR'
,p_is_translatable=>false
,p_help_text=>'Optional option name to pin first when the region loads, for example the current supplier, or a page item reference such as &P20_CURRENT_VENDOR. Diff View uses it as the baseline. Users can pin another option.'
);
wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(749811967585843031)
,p_plugin_id=>wwv_flow_imp.id(970810790386401038)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>15
,p_display_sequence=>150
,p_static_id=>'SHOW_TOTALS'
,p_prompt=>'Show Totals'
,p_attribute_type=>'CHECKBOX'
,p_is_required=>false
,p_default_value=>'Y'
,p_escape_mode=>'ATTR'
,p_is_translatable=>false
,p_help_text=>'Y shows the weighted total, rank and leading option when at least one criterion is scored (by Score or Better). N shows only the values and the best value per criterion.'
);
end;
/
